<template>
  <section class="workspace-page review-page"><div class="workspace-heading"><div><p class="workspace-eyebrow">RECALL · REFLECT · REPEAT</p><h1>把卡住的地方，学回来。</h1><p>只收录已完成练习中的真实错题。</p></div></div><div v-if="error" class="m-error" role="alert">{{ error }}<button class="m-btn m-btn--ghost m-btn--sm" @click="load">重新读取</button></div><div v-if="loading" class="m-skeleton m-skeleton--block" /><div v-else-if="!items.length && !error" class="workspace-empty"><MobileIcon name="check" :size="32" /><h2>这里暂时没有错题</h2><p>完成练习后，答错的题目会自动出现在这里。没有记录时不会补入示例。</p><RouterLink to="/learn" class="m-btn m-btn--primary m-btn--sm">去学习与练习</RouterLink></div>
    <article v-for="row in items" :key="row.exercise.id" class="m-card review-item"><div class="workspace-row"><span class="m-badge m-badge--warn">{{ row.exercise.knowledgePoint }}</span><span>{{ row.review ? `复习 ${dateLabel(row.review.dueAt)}` : '待安排复习' }}</span></div><h2>{{ row.exercise.prompt }}</h2><p>你的选择：{{ choice(row.exercise, row.attempt.submitted) }}</p><details class="workspace-details"><summary>回忆后，再看答案与解释</summary><p>正确答案：{{ choice(row.exercise, row.exercise.answer) }}</p><p>{{ row.exercise.explanation }}</p><RouterLink :to="`/study/session/${row.sessionId}/result`" class="workspace-text-action">查看原始作答记录 →</RouterLink></details><form class="workspace-form" @submit.prevent="schedule(row)"><label class="m-field"><span>这次卡在哪里？</span><select v-model="reasons[row.exercise.id]" class="m-input" required><option value="" disabled>选择或修正错因</option><option v-for="reason in reasonOptions" :key="reason">{{ reason }}</option></select></label><label class="m-field"><span>多久后再回忆一次？</span><select v-model.number="days[row.exercise.id]" class="m-input"><option v-for="day in [1,3,7,14]" :key="day" :value="day">{{ day }} 天后</option></select></label><div class="workspace-actions"><button class="m-btn m-btn--ghost m-btn--sm" :disabled="busy === row.exercise.id">保存复习安排</button><button type="button" class="m-btn m-btn--primary m-btn--sm" :disabled="!!busy" @click="practice(row)">重新练习</button></div></form><p v-if="saved === row.exercise.id" class="workspace-caption" role="status">复习时间与错因已保存，站内提醒会按偏好展示。</p></article>
  </section>
</template>
<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { apiGet } from '@/lib/api'
import MobileIcon from '@/mobile/components/MobileIcon.vue'
import { changeWorkspace, dateLabel } from '@/mobile/data/workspace'
import { createStudySession, type StudyExercise, type StudyAttempt } from '@/mobile/data/study'
interface ReviewRow { exercise: StudyExercise; attempt: StudyAttempt; sessionId: string; review: { reason: string; dueAt: string } | null }
const router = useRouter(), items = ref<ReviewRow[]>([]), loading = ref(true), error = ref(''), busy = ref(''), saved = ref(''), reasons = ref<Record<string,string>>({}), days = ref<Record<string,number>>({})
const reasonOptions = ['概念缺失', '概念混淆', '步骤错误', '读题疏漏', '记忆提取失败', '题目有争议']
function choice(exercise: StudyExercise, value: unknown) { return typeof value === 'number' ? exercise.choices?.[value] || '未记录选项' : '未记录选项' }
async function load() { error.value = ''; try { const result = await apiGet<{ items: ReviewRow[] }>('/api/workspace/reviews'); items.value = result.items; result.items.forEach(row => { reasons.value[row.exercise.id] = row.review?.reason || ''; days.value[row.exercise.id] = 3 }) } catch (e) { error.value = e instanceof Error ? e.message : '错题读取失败' } finally { loading.value = false } }
onMounted(load)
async function schedule(row: ReviewRow) { busy.value = row.exercise.id; try { await changeWorkspace('reviews', { sessionId: row.sessionId, exerciseId: row.exercise.id, reason: reasons.value[row.exercise.id], days: days.value[row.exercise.id] }); saved.value = row.exercise.id; await load() } catch (e) { error.value = e instanceof Error ? e.message : '安排失败' } finally { busy.value = '' } }
async function practice(row: ReviewRow) { busy.value = row.exercise.id; try { const result = await createStudySession([row.exercise.topicId], 3); if ('error' in result) throw new Error(result.message); await router.push(`/study/session/${result.session.id}`) } catch (e) { error.value = e instanceof Error ? e.message : '创建失败' } finally { busy.value = '' } }
</script>
<style scoped>.review-item { margin-bottom: 18px; }.review-item h2 { font-size: 18px; line-height: 1.8; }.review-item p { font-size: 14px; line-height: 1.9; color: var(--m-text-dim); }.review-item .workspace-row > span:last-child { font-size: 12px; color: var(--m-text-faint); }</style>
